# frozen_string_literal: true

# Coverage of app/ and lib/, lines and branches; the report is in coverage/index.html.
# It starts before the app loads, or the app's own files would not be counted. CI fails
# below 100% in any file (a local run of a few specs covers less, so it isn't held to
# that). Code no input can reach is wrapped in `# simplecov:disable` with the reason.
require "simplecov"
SimpleCov.start do
  enable_coverage :branch
  cover "{app,lib}/**/*.rb"
  # Generated by `hanami new` and not used yet: nothing loads them.
  skip %w[app/db/struct.rb lib/tally/types.rb]
  if ENV["CI"]
    coverage(:line) { minimum 100, per: :file }
    coverage(:branch) { minimum 100, per: :file }
  end
end

require "pathname"
SPEC_ROOT = Pathname(__dir__).realpath.freeze

ENV["HANAMI_ENV"] ||= "test"
require "hanami/prepare"

SPEC_ROOT.glob("support/**/*.rb").each { |f| require f }
